(()=>{'use strict';
const $=id=>document.getElementById(id),ids=['relLogK','relDN75','relMpDeg','relRainDeg','relSource','relModes'];
const box=document.createElement('section');box.id='availabilityInputs';box.innerHTML=`<h2>Availability · ITU-R P.530-18</h2><p class="note">ใช้ DEM + ความสูงจาน + Link budget ร่วมกับสถิติภูมิอากาศตามพิกัด · เติมค่าทั้งสามอัตโนมัติเมื่อกรอกพิกัด A–B ครบ · LogK คนละค่ากับ Earth K</p><div class="fields"><label>LogK ของพื้นที่<input id="relLogK" type="number" step="any" min="-12" max="0" placeholder="จากฐานข้อมูล P.530-18"></label><label>dN75 ของพื้นที่ (N-units)<input id="relDN75" type="number" step="any" min="0" max="200" placeholder="จากฐานข้อมูล P.530-18"></label><label>XPD degradation — multipath (dB)<input id="relMpDeg" type="number" step="any" min="0" max="100" placeholder="ว่าง = ยังไม่ทราบ"></label><label>XPD degradation — rain (dB)<input id="relRainDeg" type="number" step="any" min="0" max="100" placeholder="ว่าง = ยังไม่ทราบ"></label><label>ที่มา LogK / dN75 / R0.01<input id="relSource" maxlength="250" placeholder="ชื่อฐานข้อมูล รุ่น หรือผลสำรวจ"></label></div><p class="note">ใช้ R0.01 (mm/h) ในส่วนนี้ ไม่ใช่ rain attenuation กรณีทดสอบ · เมื่อเปิด XPIC ต้องระบุ degradation ของโหมดนั้น รวมผลที่ต้องการเผื่อจากเครื่องมือออกแบบ/ผู้ผลิต; XPD, XPIF และ C/I อย่างเดียวไม่ถูกแปลงเป็น degradation อัตโนมัติ · ช่อง degradation หลักใช้กับโหมดหลักเท่านั้น เมื่อเปรียบเทียบหลายโหมด ให้กรอก degradation ในตาราง Modulation ด้านล่าง</p><details><summary>Degradation แยกตาม modulation</summary><label>หนึ่งบรรทัด: ชื่อโหมด, Multipath dB, Rain dB<textarea id="relModes" rows="5" placeholder="32QAM, 8.97, 0.86"></textarea></label></details><p class="note">ว่าง = ไม่ทราบ ไม่แทนด้วย 0 · ใส่ 0 เมื่อยืนยันว่าไม่เผื่อ · ผลเป็นประมาณการด้านการแพร่คลื่น ยังไม่รวม frequency-selective fading, diversity, หิมะเปียก, ไฟฟ้าดับ และอุปกรณ์เสีย</p>`;
$('mwForm').append(box);
const out=document.createElement('section');out.id='availabilityResults';out.innerHTML='<h2>Annual Availability / Outage</h2><div id="availabilityOutput"></div>';$('results').append(out);
function read(){const optional=id=>$(id).value.trim()===''?null:Number($(id).value);const modeDegradation=Object.create(null);for(const line of $('relModes').value.split('\n').filter(x=>x.trim())){const cells=line.split(',').map(x=>x.trim());if(cells.length!==3||!cells[0]||cells.slice(1).some(x=>x!==''&&(!Number.isFinite(+x)||+x<0)))throw Error('ตรวจ Degradation ราย modulation: ชื่อ, multipath dB, rain dB');if(modeDegradation[cells[0]])throw Error('ชื่อ modulation ซ้ำใน Degradation: '+cells[0]);modeDegradation[cells[0]]=cells.slice(1).map(x=>x===''?null:Number(x))}return {logK:optional('relLogK'),dN75:optional('relDN75'),mpDeg:optional('relMpDeg'),rainDeg:optional('relRainDeg'),source:$('relSource').value,climate:globalThis.MWClimateUI?.metadata(),modeDegradation}}
const n=(x,d=6)=>Number.isFinite(x)?x.toFixed(d):'—',range=(lo,hi,d=6)=>Math.abs(hi-lo)<1e-12?n(lo,d):n(lo,d)+' – '+n(hi,d);
function render(c,r){const s=c.availability||read(),a=MWAvailability.evaluate(c,r,s);const problems=[...new Set(a.rows.flatMap(x=>x.errors))];
 let html='<p class="availability-note">ประมาณการเวลาที่สัญญาณต่ำกว่าเกณฑ์รับของแต่ละโหมด (ปีละ 365 วัน) · ต่อทิศทางและโพลาไรซ์ · ไม่ใช่ SLA และไม่แยกเหตุขัดข้องที่นานเกิน 10 วินาที</p>';
 html+=table(['ข้อมูลใช้คำนวณ','ค่า'],[['วิธี','P.530-18 §§2.3.1–2.3.4, 2.4.1 + P.838-3'],['LogK / dN75',n(s.logK,5)+' / '+n(s.dN75,3)],['R0.01',n(c.rainRate,2)+' mm/h'],['การเลือกข้อมูล',s.climate?.mode==='auto'?'อัตโนมัติ · กึ่งกลางลิงก์ '+n(s.climate.lat,6)+', '+n(s.climate.lon,6):'กรอกเอง'],['ที่มาสถิติ',s.source||'ยังไม่ระบุ — ตรวจสอบค่าก่อนใช้ออกแบบ'],['DEM เฉลี่ย ht / mean clearance hc',n(a.mp.ht,2)+' / '+n(a.mp.hc,2)+' m'],['Multipath p0 / ΔG',n(a.mp.p0,6)+' % / '+n(a.mp.delta,3)+' dB'],...Object.entries(a.rain).map(([pol,v])=>['ฝน '+pol+' : γR / A0.01',v.error||n(v.gamma,4)+' dB/km / '+n(v.a001,3)+' dB'])]);
 if(a.mp.note)html+='<p class="availability-warning">'+esc(a.mp.note)+'</p>';
 if(problems.length)html+='<p class="availability-warning">'+problems.map(esc).join('<br>')+'</p>';
 const columns=[...new Set(a.rows.map(x=>x.direction+'|'+x.pol))],modes=[...new Set(a.rows.map(x=>x.mode))];
 html+='<h3>เปรียบเทียบทุก Modulation</h3><p class="note">แต่ละช่อง: Availability % / Outage นาทีต่อปี · ช่วงตัวเลขหมายถึงขอบเขตประมาณการจากสูตรฝน · ไม่ใช่สัดส่วนเวลาที่ AM เลือกใช้โหมดนั้น</p><div class="availability-scroll" id="modulationComparison">'+table(['Modulation / Mbps',...columns.map(k=>{const [dir,pol]=k.split('|');return (dir==='ab'?'A → B':'B → A')+' / '+pol;})],modes.map(mode=>{const rows=a.rows.filter(x=>x.mode===mode);return [mode+' / '+rows[0].capacity,...columns.map(k=>{const x=rows.find(x=>x.direction+'|'+x.pol===k);return x?.total?range(100-x.total.hi,100-x.total.lo)+' % / '+range(x.total.lo*5256,x.total.hi*5256,2)+' นาที':'ข้อมูลไม่ครบ / นอกขอบเขต';})]}))+'</div>';
 html+='<details class="mode-detail"><summary>รายละเอียด Fade margin และ Outage แยกสาเหตุ</summary><div class="availability-scroll">'+table(['โหมด / Mbps','ทิศ / Pol','Thermal margin dB','Flat / Rain margin dB','Multipath outage ต่อปี %','Rain outage ต่อปี %','Availability ต่อปี %','Outage นาที/ปี'],a.rows.map(x=>[x.mode+' / '+x.capacity,(x.direction==='ab'?'A → B':'B → A')+' / '+x.pol,n(x.thermal,2),n(x.flat,2)+' / '+n(x.wet,2),n(x.annual),x.rain.error?'—':x.rain.bound?(x.rain.lo===0?'< 0.001':'> 1'):n(x.rain.lo),x.total?range(100-x.total.hi,100-x.total.lo):'ข้อมูลไม่ครบ / นอกขอบเขต',x.total?range(x.total.lo*5256,x.total.hi*5256,2):'—']))+'</div></details>';
 html+='<p class="availability-note">รวม outage ต่อทิศทาง = multipath + rain (จำกัดไม่เกิน 100%) · H+V แสดงทั้งสองโพลาไรซ์ ไม่รวมเป็นความจุของ 2+0 โดยอัตโนมัติ · ไม่บวก outage ของ A→B และ B→A เป็นค่ารวม เพราะเหตุขัดข้องอาจเกิดพร้อมกัน</p><p class="availability-note">เมื่อฝนให้ outage ต่ำกว่า 0.001% หรือสูงกว่า 1% ซึ่งอยู่นอกช่วงสมการ (34) จะรายงานเป็นขอบเขตและแสดง Availability/นาทีเป็นช่วง ไม่ extrapolate เป็นค่าจุด · แถวที่ข้อมูลไม่ครบไม่ใช่ 100% availability</p><p class="note">อ้างอิง: <a href="https://www.itu.int/rec/R-REC-P.530-18-202109-S/en" target="_blank" rel="noopener">ITU-R P.530-18</a> · <a href="https://www.itu.int/rec/R-REC-P.838-3-200503-I/en" target="_blank" rel="noopener">ITU-R P.838-3</a></p>';
 $('availabilityOutput').innerHTML=html;
}
const example=$('example').onclick;$('example').onclick=()=>{example();$('relLogK').value=-5.34916;$('relDN75').value='';$('relMpDeg').value=8.97;$('relRainDeg').value=.86;$('relSource').value='PDF ตัวอย่าง: LogK/R0.01/degradation; ไม่มี dN75';$('relModes').value='512QAM,2.02,2.11\n256QAM,2.79,2.02\n128QAM,5.06,2.17\n64QAM,6.5,1.99\n32QAM,8.97,0.86';dirty()};
try{const saved=JSON.parse(localStorage.getItem('rf-microwave-v1')||'{}');for(const id of ids)if(saved[id]!==undefined)$(id).value=saved[id]}catch{}
globalThis.MWAvailabilityUI={read,render};
})();
